   277  void Flow::deferredInitialization() {
   278    if (cli_host && srv_host) {
   279      char country[64];
   280
   281      if (cli_host->isLocalHost()) {
   282        srv_host->get_country(country, sizeof(country));
   283        if (country[0] != '\0') cli_host->incCountriesContacts(country);
   284
   285        Mac *srv_mac = srv_host->getMac();
   286        /* Add client gateway */
   287        if (srv_mac && (!srv_host->isLocalHost())) {
   288          LocalHost *lh = (LocalHost *)cli_host;
   289          lh->setRouterMac(srv_mac);
   290        }
   291      }
   292
   293      if (srv_host->isLocalHost()) {
   294        cli_host->get_country(country, sizeof(country));
   295        if (country[0] != '\0') srv_host->incCountriesContacts(country);
   296      }
   297    }
   298
   299    if (isBlacklistedClient()) {
   300      if (srv_host) srv_host->inc_num_blacklisted_flows(false);
   301    } else if (isBlacklistedServer()) {
   302      if (cli_host) cli_host->inc_num_blacklisted_flows(true);
   303    }
   304
   305    iface->execFlowBeginChecks(this);
   306  }
