    79  void GenericHash::cleanup() {
    80    vector<GenericHashEntry *> **ghvs[] = {&idle_entries, &idle_entries_shadow,
    81                                           &idle_entries_in_use};
    82
    83    for (u_int i = 0; i < sizeof(ghvs) / sizeof(ghvs[0]); i++) {
    84      if (*ghvs[i]) {
    85        if (!(*ghvs[i])->empty()) {
    86          for (vector<GenericHashEntry *>::const_iterator it =
    87                   (*ghvs[i])->begin();
    88               it != (*ghvs[i])->end(); ++it) {
    89            delete *it;
    90          }
    91        }
    92
    93        delete *ghvs[i];
    94        *ghvs[i] = NULL;
    95      }
    96    }
    97
    98    for (u_int i = 0; i < num_hashes; i++) {
    99      if (table[i] != NULL) {
   100        GenericHashEntry *head = table[i];
   101
   102        while (head) {
   103          GenericHashEntry *next = head->next();
   104
   105          delete (head);
   106          head = next;
   107        }
   108
   109        table[i] = NULL;
   110      }
   111    }
   112
   113    current_size = 0;
   114  }
