   432    if (isHTTP()) {
   433      if (protos.http.last_url) free(protos.http.last_url);
   434      if (protos.http.last_user_agent) free(protos.http.last_user_agent);
   435      if (protos.http.last_server) free(protos.http.last_server);
   436    } else if (isDNS()) {
   437      if (protos.dns.last_query) free(protos.dns.last_query);
   438      if (protos.dns.last_query_shadow) free(protos.dns.last_query_shadow);
   439    } else if (isMDNS()) {
   440      if (protos.mdns.answer) free(protos.mdns.answer);
   441      if (protos.mdns.name) free(protos.mdns.name);
   442      if (protos.mdns.name_txt) free(protos.mdns.name_txt);
   443      if (protos.mdns.ssid) free(protos.mdns.ssid);
   444    } else if (isSSDP()) {
   445      if (protos.ssdp.location) free(protos.ssdp.location);
   446    } else if (isNetBIOS()) {
   447      if (protos.netbios.name) free(protos.netbios.name);
   448    } else if (isSSH()) {
   449      if (protos.ssh.client_signature) free(protos.ssh.client_signature);
   450      if (protos.ssh.server_signature) free(protos.ssh.server_signature);
   451      if (protos.ssh.hassh.client_hash) free(protos.ssh.hassh.client_hash);
   452      if (protos.ssh.hassh.server_hash) free(protos.ssh.hassh.server_hash);
   453    } else if (isTLS()) {
   454      if (protos.tls.client_requested_server_name)
   455        free(protos.tls.client_requested_server_name);
   456      if (protos.tls.server_names) free(protos.tls.server_names);
   457      if (protos.tls.ja3.client_hash) free(protos.tls.ja3.client_hash);
   458      if (protos.tls.ja3.server_hash) free(protos.tls.ja3.server_hash);
   459      if (protos.tls.client_alpn) free(protos.tls.client_alpn);
   460      if (protos.tls.client_tls_supported_versions)
   461        free(protos.tls.client_tls_supported_versions);
   462      if (protos.tls.issuerDN) free(protos.tls.issuerDN);
   463      if (protos.tls.subjectDN) free(protos.tls.subjectDN);
   464    }
   465
   466    if (bt_hash) free(bt_hash);
   467
   468    freeDPIMemory();
   469    if (icmp_info) delete (icmp_info);
   470    if (json_protocol_info) free(json_protocol_info);
   471    if (external_alert.json) json_object_put(external_alert.json);
   472    if (external_alert.source) free(external_alert.source);
   473
   474    if (customFlowAlert.msg) free(customFlowAlert.msg);
   475  }
