   488  void HTTPstats::incStats(bool as_client, const FlowHTTPStats *fts) {
   489    struct http_query_stats *q =
   490        as_client ? &query[AS_SENDER] : &query[AS_RECEIVER];
   491    struct http_response_stats *r =
   492        as_client ? &response[AS_RECEIVER] : &response[AS_SENDER];
   493
   494    if (fts->num_get) q->num_get += fts->num_get;
   495    if (fts->num_post) q->num_post += fts->num_post;
   496    if (fts->num_head) q->num_head += fts->num_head;
   497    if (fts->num_put) q->num_put += fts->num_put;
   498    if (fts->num_other) q->num_other += fts->num_other;
   499
   500    if (fts->num_1xx) r->num_1xx += fts->num_1xx;
   501    if (fts->num_2xx) r->num_2xx += fts->num_2xx;
   502    if (fts->num_3xx) r->num_3xx += fts->num_3xx;
   503    if (fts->num_4xx) r->num_4xx += fts->num_4xx;
   504    if (fts->num_5xx) r->num_5xx += fts->num_5xx;
   505  }
