   508
   509  bool HTTPstats::updateHTTPHostRequest(time_t t, char *virtual_host_name,
   510                                        u_int32_t num_requests,
   511                                        u_int32_t bytes_sent,
   512                                        u_int32_t bytes_rcvd) {
   513    VirtualHost *vh;
   514    bool rc = false;
   515
   516    if ((num_requests == 0) && (bytes_sent == 0) && (bytes_rcvd == 0))
   517      return (rc);
   518
   519    if (!virtualHosts) return (rc); /* Looks like we're running out of memory */
   520
   521    /*
   522      Needed because this method can be called by both
   523      NetworkInterface::updateHostStats() and
   524      Flow::~Flow() on the same instance and thus
   525      create a memory leak
   526    */
   527    if ((vh = virtualHosts->get(virtual_host_name)) == NULL) {
   528      if (virtualHosts->hasEmptyRoom()) {
   529        if ((vh = new (std::nothrow) VirtualHost(h, virtual_host_name)) == NULL) {
   530          ntop->getTrace()->traceEvent(
   531              TRACE_WARNING, "Internal error: are you running out of memory?");
   532        } else {
   533          if(virtualHosts->add(vh, false /* no need to lock the bucket, purgeIdle is sequential wrt to this */) == false) {
   534            /* Unable to add a new virtual host */
   535            delete vh;
   536            vh = NULL;
   537          } else
   538            rc = true;
   539        }
   540      }
   541    }
   542
   543    if (vh) vh->incStats(t, num_requests, bytes_sent, bytes_rcvd);
   544
   545    return (rc);
   546  }
